#!/usr/bin/env python3
import re

def modify_nml(nml_path, params):
    """Modify GLM configuration parameters"""
    with open(nml_path, 'r') as f:
        content = f.read()

    for param, value in params.items():
        if isinstance(value, str):
            pattern = rf"({param}\s*=\s*)'[^']*'"
            replacement = rf"\g<1>'{value}'"
        elif isinstance(value, bool):
            pattern = rf"({param}\s*=\s*)\.(?:true|false)\."
            replacement = rf"\g<1>."
            if value:
                replacement += "true."
            else:
                replacement += "false."
        else:
            pattern = rf"({param}\s*=\s*)[+\-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+\-]?\d+)?"
            replacement = rf"\g<1>{value}"

        content = re.sub(pattern, replacement, content)

    with open(nml_path, 'w') as f:
        f.write(content)

# Fine-tune: increase Kw for more light absorption
# Increase wind_factor slightly (was too aggressive before)
# Reduce shear mixing coefficient
params = {
    'Kw': 0.5,  # Increased from 0.45 to 0.5
    'wind_factor': 0.9,  # Increased from 0.8 to 0.9
    'coef_mix_shear': 0.25,  # Reduced from 0.3 to 0.25
}

print("Fine-tuning GLM parameters:")
for param, value in params.items():
    print(f"  {param}: {value}")

modify_nml('glm3.nml', params)
print("\nParameter changes applied")

